SELECT c.id, c.post_id, c.user_id, c.parent_id, c.reply_to_id, c.content, c.html_content, c.like_count, c.dislike_count, c.reply_count, c.level, c.path, c.status, c.is_pinned, c.is_author_reply, c.edited_at, c.created_at, c.updated_at,
-- 用户基本信息 u.id AS user_id, u.username AS user_username, up.display_name AS user_display_name, up.avatar_url AS user_avatar_url, up.bio AS user_bio, u.status AS user_status, u.created_at AS user_created_at, -- 判断评论用户是否为当前文章的作者 CASE WHEN p.author_id = c.user_id THEN true ELSE false END AS user_is_blog_author
FROM comments c LEFT JOIN "user" u ON c.user_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id LEFT JOIN posts p ON c.post_id = p.id WHERE c.post_id = #{postId} AND c.parent_id IS NULL AND c.deleted_at IS NULL
AND c.user_id = #{params.userId}
AND c.status = #{params.status}
AND c.is_pinned = #{params.isPinned}
AND c.is_author_reply = #{params.isAuthorReply}
AND (c.content ILIKE CONCAT('%', #{params.keyword}, '%') OR c.html_content ILIKE CONCAT('%', #{params.keyword}, '%'))
ORDER BY c.is_pinned DESC, c.created_at ASC

SELECT COUNT(*)
FROM comments
WHERE parent_id = #{parentId}
  AND post_id = #{postId}
  AND deleted_at IS NULL
  AND status = 'APPROVED'

SELECT c.id, c.post_id, c.user_id, c.parent_id, c.reply_to_id, c.content, c.html_content, c.like_count, c.dislike_count, c.reply_count, c.level, c.path, c.status, c.is_pinned, c.is_author_reply, c.edited_at, c.created_at, c.updated_at,
-- 用户基本信息 u.id AS user_id, u.username AS user_username, up.display_name AS user_display_name, up.avatar_url AS user_avatar_url, up.bio AS user_bio, u.status AS user_status, u.created_at AS user_created_at, -- 判断评论用户是否为当前文章的作者 CASE WHEN p.author_id = c.user_id THEN true ELSE false END AS user_is_blog_author
FROM comments c LEFT JOIN "user" u ON c.user_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id LEFT JOIN posts p ON c.post_id = p.id WHERE c.parent_id = #{parentId} AND c.post_id = #{postId} AND c.deleted_at IS NULL AND c.status = 'APPROVED' ORDER BY c.created_at ASC OFFSET #{offset} LIMIT #{limit}

SELECT c.id, c.post_id, c.user_id, c.parent_id, c.reply_to_id, c.content, c.html_content, c.like_count, c.dislike_count, c.reply_count, c.level, c.path, c.status, c.is_pinned, c.is_author_reply, c.edited_at, c.created_at, c.updated_at,
-- 用户基本信息 u.id AS user_id, u.username AS user_username, up.display_name AS user_display_name, up.avatar_url AS user_avatar_url, up.bio AS user_bio, u.status AS user_status, u.created_at AS user_created_at, -- 判断评论用户是否为当前文章的作者 CASE WHEN p.author_id = c.user_id THEN true ELSE false END AS user_is_blog_author
FROM comments c LEFT JOIN "user" u ON c.user_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id LEFT JOIN posts p ON c.post_id = p.id WHERE c.user_id = #{userId} AND c.deleted_at IS NULL
AND c.post_id = #{postId}
AND c.status = #{status}
ORDER BY c.created_at DESC

SELECT c.id, c.post_id, c.user_id, c.parent_id, c.reply_to_id, c.content, c.html_content, c.like_count, c.dislike_count, c.reply_count, c.level, c.path, c.status, c.is_pinned, c.is_author_reply, c.ip_address, c.user_agent, c.edited_at, c.created_at, c.updated_at,
-- 用户基本信息 u.id AS user_id, u.username AS user_username, up.display_name AS user_display_name, up.avatar_url AS user_avatar_url, up.bio AS user_bio, u.status AS user_status, u.created_at AS user_created_at, -- 判断评论用户是否为当前文章的作者 CASE WHEN p.author_id = c.user_id THEN true ELSE false END AS user_is_blog_author
FROM comments c LEFT JOIN "user" u ON c.user_id = u.id LEFT JOIN user_profiles up ON u.id = up.user_id LEFT JOIN posts p ON c.post_id = p.id WHERE 1=1
AND c.status = #{params.status}
AND c.post_id = #{params.postId}
AND c.user_id = #{params.userId}
AND EXISTS (SELECT 1 FROM comment_reports cr WHERE cr.comment_id = c.id)
AND c.content ILIKE CONCAT('%', #{params.keyword}, '%')
ORDER BY c.created_at DESC
